// ==========================================
// ⚙️ ЛОГИКА РАБОТЫ ТРЕНАЖЁРА
// ==========================================

let currentQuestions = [];
let currentTopic = '';
let currentQuestion = 0;
let answered = false;
let questionStatus = []; 
let timerInterval;
let secondsElapsed = 0;

// DOM элементы
const mainMenu = document.getElementById('mainMenu');
const quizApp = document.getElementById('quizApp');
const headerTitle = document.getElementById('headerTitle');
const questionText = document.getElementById('questionText');
const optionsContainer = document.getElementById('optionsContainer');
const inputContainer = document.getElementById('inputContainer');
const textInput = document.getElementById('textInput');
const submitBtn = document.getElementById('submitBtn');
const explanationBox = document.getElementById('explanationBox');
const explanationText = document.getElementById('explanationText');
const nextBtn = document.getElementById('nextBtn');
const progressBar = document.getElementById('progressBar');
const progressText = document.getElementById('progressText');
const questionNav = document.getElementById('questionNav');
const resultsScreen = document.getElementById('resultsScreen');
const finalScore = document.getElementById('finalScore');
const finalGrade = document.getElementById('finalGrade');

// Запуск темы
document.querySelectorAll('.topic-card').forEach(card => {
    card.addEventListener('click', () => {
        currentTopic = card.dataset.topic;
        
        if (!questionsDB[currentTopic] || questionsDB[currentTopic].length === 0) {
            alert("Вопросы для этой темы ещё не добавлены! Выбери другую.");
            return;
        }

        currentQuestions = questionsDB[currentTopic];
        
        currentQuestion = 0;
        questionStatus = [];
        secondsElapsed = 0;
        
        mainMenu.style.display = 'none';
        quizApp.style.display = 'block';
        resultsScreen.style.display = 'none';
        quizApp.querySelector('.quiz-card').style.display = 'flex';
        questionNav.style.display = 'flex';
        
        const topicNames = {
            genetics: 'Генетика',
            evolution: 'Эволюция',
            cell: 'Клетка',
            ecology: 'Экология',
            metabolism: 'Обмен веществ',
            anatomy: 'Анатомия'
        };
        headerTitle.textContent = topicNames[currentTopic] || 'Тест';
        
        startTimer();
        loadQuestion();
    });
});

// Кнопка Назад
document.getElementById('exitBtn').addEventListener('click', () => {
    clearInterval(timerInterval);
    quizApp.style.display = 'none';
    mainMenu.style.display = 'block';
});

function startTimer() {
    clearInterval(timerInterval);
    const timerText = document.getElementById('timerText');
    timerText.textContent = '⏱ 0:00';
    
    timerInterval = setInterval(() => {
        secondsElapsed++;
        const m = Math.floor(secondsElapsed / 60);
        const s = secondsElapsed % 60;
        timerText.textContent = `⏱ ${m}:${s < 10 ? '0' + s : s}`;
    }, 1000);
}

function renderNav() {
    questionNav.innerHTML = '';
    currentQuestions.forEach((_, index) => {
        const btn = document.createElement('button');
        btn.className = 'nav-btn';
        btn.textContent = index + 1;
        
        if (index === currentQuestion) btn.classList.add('active');
        if (questionStatus[index] === 'correct') btn.classList.add('answered-correct');
        if (questionStatus[index] === 'wrong') btn.classList.add('answered-wrong');

        btn.onclick = () => {
            currentQuestion = index;
            loadQuestion();
        };
        questionNav.appendChild(btn);
    });
}

function loadQuestion() {
    answered = false;
    const q = currentQuestions[currentQuestion];
    
    progressText.textContent = `Вопрос ${currentQuestion + 1} из ${currentQuestions.length} (${q.topic})`;
    progressBar.style.width = `${((currentQuestion) / currentQuestions.length) * 100}%`;

    questionText.innerHTML = q.question.replace(/\n/g, '<br>');
    explanationBox.classList.remove('show');
    nextBtn.classList.remove('show');
    
    optionsContainer.style.display = 'none';
    inputContainer.style.display = 'none';
    optionsContainer.innerHTML = '';
    
    textInput.value = '';
    textInput.classList.remove('correct', 'wrong', 'correct-anim', 'wrong-anim');
    textInput.disabled = false;
    submitBtn.disabled = false;
    submitBtn.style.display = 'block';

    const checkOptionsBtn = document.getElementById('checkOptionsBtn');
    checkOptionsBtn.style.display = 'none'; 

    if (questionStatus[currentQuestion] === undefined) {
        document.getElementById('skipBtn').style.display = 'block';
    } else {
        document.getElementById('skipBtn').style.display = 'none';
    }

    if (q.type === 'options') {
        optionsContainer.style.display = 'flex';
        nextBtn.textContent = currentQuestion === currentQuestions.length - 1 ? 'Узнать результат 🎉' : 'Следующий вопрос →';
        
        if (q.correctIndexes && q.correctIndexes.length > 1) {
            checkOptionsBtn.style.display = 'block';
            checkOptionsBtn.disabled = false;
        }

        let selectedOptions = [];
        let optionsList = q.options.map((text, index) => ({
            text: text,
            isCorrect: q.correctIndexes.includes(index),
            originalIndex: index
        }));

        optionsList.forEach(opt => {
            const btn = document.createElement('button');
            btn.className = 'option-btn';
            btn.textContent = opt.text;
            
            btn.addEventListener('click', () => {
                if (answered) return;

                if (!q.correctIndexes || q.correctIndexes.length === 1) {
                    handleOptionClick(btn, opt.isCorrect, q);
                } else {
                    if (btn.classList.contains('selected')) {
                        btn.classList.remove('selected');
                        selectedOptions = selectedOptions.filter(i => i !== opt.originalIndex);
                    } else {
                        btn.classList.add('selected');
                        selectedOptions.push(opt.originalIndex);
                    }
                }
            });
            optionsContainer.appendChild(btn);
        });

        checkOptionsBtn.onclick = () => {
            if (answered) return;
            answered = true;
            checkOptionsBtn.disabled = true;
            checkOptionsBtn.style.display = 'none';
            document.getElementById('skipBtn').style.display = 'none';

            const allButtons = document.querySelectorAll('.option-btn');
            allButtons.forEach(b => b.classList.add('disabled'));

            const isCorrect = (selectedOptions.length === q.correctIndexes.length) && 
                              selectedOptions.every(val => q.correctIndexes.includes(val));

            if (isCorrect) {
                allButtons.forEach(b => {
                    const idx = q.options.indexOf(b.textContent);
                    if (q.correctIndexes.includes(idx)) b.classList.add('correct');
                });
                questionStatus[currentQuestion] = 'correct';
                explanationText.textContent = "✅ Верно! " + q.explanation;
                explanationBox.className = 'explanation show correct-bg';
            } else {
                allButtons.forEach(b => {
                    const idx = q.options.indexOf(b.textContent);
                    if (selectedOptions.includes(idx) && !q.correctIndexes.includes(idx)) b.classList.add('wrong');
                    if (q.correctIndexes.includes(idx)) b.classList.add('correct');
                });
                questionStatus[currentQuestion] = 'wrong';
                explanationText.textContent = "❌ Ошибка. " + q.explanation;
                explanationBox.className = 'explanation show wrong-bg';
            }
            showNextBtn();
            renderNav();
        };
    } else if (q.type === 'input') {
        inputContainer.style.display = 'flex';
        nextBtn.textContent = currentQuestion === currentQuestions.length - 1 ? 'Узнать результат 🎉' : 'Следующий вопрос →';
        textInput.focus();
    }
    
    renderNav();
}

function handleOptionClick(btn, isCorrect, q) {
    if (answered) return;
    answered = true;
    document.getElementById('skipBtn').style.display = 'none';

    const allButtons = document.querySelectorAll('.option-btn');
    allButtons.forEach(b => b.classList.add('disabled'));

    if (isCorrect) {
        btn.classList.add('correct', 'correct-anim');
        questionStatus[currentQuestion] = 'correct';
        explanationText.textContent = "✅ Верно! " + q.explanation;
        explanationBox.className = 'explanation show correct-bg';
    } else {
        btn.classList.add('wrong', 'wrong-anim');
        questionStatus[currentQuestion] = 'wrong';
        allButtons.forEach((b) => {
            const originalIndex = q.options.indexOf(b.textContent);
            if (q.correctIndexes.includes(originalIndex)) {
                b.classList.add('correct');
            }
        });
        explanationText.textContent = "❌ Ошибка. " + q.explanation;
        explanationBox.className = 'explanation show wrong-bg';
    }
    showNextBtn();
    renderNav();
}

function handleInputSubmit() {
    if (answered) return;
    const q = currentQuestions[currentQuestion];
    
    answered = true;
    textInput.disabled = true;
    submitBtn.disabled = true;
    submitBtn.style.display = 'none';
    document.getElementById('skipBtn').style.display = 'none';
    
    let userAnswer = textInput.value.trim().toLowerCase().replace(/ё/g, 'е');
    let isCorrectInput = false;

    if (q.correctAnswer instanceof RegExp) {
        isCorrectInput = q.correctAnswer.test(textInput.value.trim());
    } else {
        isCorrectInput = q.correctAnswer.some(ans => ans.toLowerCase().replace(/ё/g, 'е') === userAnswer);
    }

    if (isCorrectInput) {
        textInput.classList.add('correct', 'correct-anim');
        questionStatus[currentQuestion] = 'correct';
        explanationText.textContent = "✅ Верно! " + q.explanation;
        explanationBox.className = 'explanation show correct-bg';
    } else {
        textInput.classList.add('wrong', 'wrong-anim');
        questionStatus[currentQuestion] = 'wrong';
        explanationText.textContent = "❌ Ошибка. " + q.explanation;
        explanationBox.className = 'explanation show wrong-bg';
    }
    showNextBtn();
    renderNav();
}

function showNextBtn() {
    nextBtn.classList.add('show');
    if (currentQuestion === currentQuestions.length - 1) progressBar.style.width = '100%';
}

document.getElementById('skipBtn').addEventListener('click', () => {
    let nextUnanswered = -1;
    for (let i = 1; i <= currentQuestions.length; i++) {
        let checkIndex = (currentQuestion + i) % currentQuestions.length;
        if (questionStatus[checkIndex] === undefined) {
            nextUnanswered = checkIndex;
            break;
        }
    }
    
    if (nextUnanswered !== -1) {
        currentQuestion = nextUnanswered;
        loadQuestion();
    } else {
        currentQuestion++;
        if (currentQuestion < currentQuestions.length) {
            loadQuestion();
        } else {
            showResults();
        }
    }
});

submitBtn.addEventListener('click', handleInputSubmit);
textInput.addEventListener('keypress', (e) => {
    if (e.key === 'Enter') handleInputSubmit();
});

nextBtn.addEventListener('click', () => {
    currentQuestion++;
    if (currentQuestion < currentQuestions.length) {
        loadQuestion();
    } else {
        showResults();
    }
});

function showResults() {
    clearInterval(timerInterval);
    quizApp.querySelector('.quiz-card').style.display = 'none';
    questionNav.style.display = 'none';
    resultsScreen.style.display = 'block';
    
    let total = currentQuestions.length;
    let finalScoreVal = questionStatus.filter(status => status === 'correct').length;
    let percent = (finalScoreVal / total) * 100;
    let grade = 2;

    if (percent >= 85) grade = 5;
    else if (percent >= 65) grade = 4;
    else if (percent >= 40) grade = 3;
    else grade = 2;

    finalScore.textContent = `${finalScoreVal}/${total}`;
    
    finalGrade.textContent = grade;
    finalGrade.className = 'grade-mark';
    if (grade === 5) finalGrade.classList.add('grade-5');
    if (grade === 4) finalGrade.classList.add('grade-4');
    if (grade === 3) finalGrade.classList.add('grade-3');
    if (grade === 2) finalGrade.classList.add('grade-2');

    const restartBtn = document.getElementById('restartBtn');
    restartBtn.textContent = 'Вернуться в меню 🏠';
    restartBtn.onclick = () => {
        resultsScreen.style.display = 'none';
        quizApp.style.display = 'none';
        mainMenu.style.display = 'block';
    };

    if (grade === 5 || grade === 4) {
        launchConfetti();
    }
}

function launchConfetti() {
    const canvas = document.getElementById('confetti-canvas');
    if(!canvas) return;
    const ctx = canvas.getContext('2d');
    canvas.style.display = 'block';
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;

    const particles = [];
    const colors = ['#22c55e', '#10b981', '#14b8a6', '#3b82f6', '#8b5cf6'];

    for (let i = 0; i < 150; i++) {
        particles.push({
            x: Math.random() * canvas.width,
            y: Math.random() * canvas.height - canvas.height,
            size: Math.random() * 8 + 4,
            speedY: Math.random() * 3 + 2,
            speedX: Math.random() * 2 - 1,
            color: colors[Math.floor(Math.random() * colors.length)],
            rotation: Math.random() * 360,
            rotationSpeed: Math.random() * 10 - 5
        });
    }

    function animate() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        particles.forEach((p, index) => {
            p.y += p.speedY;
            p.x += p.speedX;
            p.rotation += p.rotationSpeed;

            ctx.save();
            ctx.translate(p.x, p.y);
            ctx.rotate(p.rotation * Math.PI / 180);
            ctx.fillStyle = p.color;
            ctx.fillRect(-p.size / 2, -p.size / 2, p.size, p.size);
            ctx.restore();

            if (p.y > canvas.height) {
                particles.splice(index, 1);
            }
        });

        if (particles.length > 0) {
            requestAnimationFrame(animate);
        } else {
            canvas.style.display = 'none';
        }
    }
    animate();
}

document.getElementById('themeToggle').addEventListener('click', () => {
    document.body.classList.toggle('dark-mode');
    document.body.classList.toggle('light-mode');
});
